/**
 * public-claim-status.route.js
 *
 * Public (no-auth) claim-status lookup — the QR-code target generated by
 * insurance-claim-notify.service.js's generateStatusQrCode(). Returns only
 * non-clinical status fields; no diagnosis/treatment/document data.
 *
 * GET /api/public/claim-status/:token
 * Token payload: { claimId, claimNumber, purpose: 'claim-status-lookup' }
 */
import express from 'express';
import jwt from 'jsonwebtoken';
import pool from '../db/pgPool.js';
import { withRlsTransaction } from '../middleware/rls-context.middleware.js';
import logger from '../config/logger.js';

const router = express.Router();

router.get('/:token', async (req, res) => {
  const { token } = req.params;

  let payload;
  try {
    payload = jwt.verify(token, process.env.JWT_SECRET);
  } catch (err) {
    return res.status(410).json({ success: false, message: 'This status link has expired or is invalid.' });
  }

  if (payload.purpose !== 'claim-status-lookup') {
    return res.status(400).json({ success: false, message: 'Invalid link.' });
  }

  try {
    // insurance_claims has row-level security keyed on organization_id; this
    // is an intentionally public, token-gated read of a handful of non-PHI
    // fields, so it runs with the platform-admin RLS bypass rather than an
    // org context this request doesn't have.
    const row = await withRlsTransaction(pool, { orgId: 0, userId: 0, isPlatformAdmin: true }, async (client) => {
      const r = await client.query(
        `SELECT claim_number, status, settlement_status, insurance_provider,
                claim_amount, approved_amount, settled_amount,
                submitted_date, approval_date, payment_date, updated_at
         FROM insurance_claims
         WHERE id = $1 AND claim_number = $2`,
        [payload.claimId, payload.claimNumber]
      );
      return r.rows[0] || null;
    });

    if (!row) {
      return res.status(404).json({ success: false, message: 'Claim not found.' });
    }

    res.json({
      success: true,
      claim: {
        claimNumber: row.claim_number,
        status: row.status,
        settlementStatus: row.settlement_status,
        insurer: row.insurance_provider,
        claimAmount: row.claim_amount,
        approvedAmount: row.approved_amount,
        settledAmount: row.settled_amount,
        submittedDate: row.submitted_date,
        approvalDate: row.approval_date,
        paymentDate: row.payment_date,
        lastUpdated: row.updated_at,
      },
    });
  } catch (err) {
    logger.error(`[publicClaimStatus] error: ${err.message}`);
    res.status(500).json({ success: false, message: 'Unable to retrieve claim status. Please try again later.' });
  }
});

export default router;
